-- Apply in a dedicated Supabase project. Never apply to a Wilmotos database.
begin;
create type public.app_role as enum ('citizen','analyst','reviewer','admin');
create table public.citizens (
 id uuid primary key references auth.users(id) on delete cascade,
 role public.app_role not null default 'citizen', created_at timestamptz not null default now()
);
create function public.app_role() returns text language sql stable security definer set search_path = '' as $$
 select coalesce((select role::text from public.citizens where id=auth.uid()),'visitor');
$$;
create function public.new_citizen() returns trigger language plpgsql security definer set search_path = '' as $$
begin insert into public.citizens(id) values(new.id); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_citizen();
create table public.municipalities(id uuid primary key default gen_random_uuid(),ibge_code char(7) not null unique check(ibge_code ~ '^[0-9]{7}$'),name text not null,state char(2) not null);
create table public.sources(id uuid primary key default gen_random_uuid(),name text not null,url text not null check(url like 'https://%'),format text not null,frequency text,limitations text,verified_at timestamptz,unique(url));
create table public.agencies(id uuid primary key default gen_random_uuid(),municipality_id uuid not null references public.municipalities(id),name text not null,external_id text not null,source_id uuid not null references public.sources(id),collected_at timestamptz not null,verified boolean not null default false,unique(source_id,external_id));
create table public.companies(id uuid primary key default gen_random_uuid(),tax_id char(14) unique check(tax_id ~ '^[0-9]{14}$'),name text not null,source_id uuid not null references public.sources(id),external_id text not null,collected_at timestamptz not null,verified boolean not null default false,unique(source_id,external_id));
create table public.tenders(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies(id),object text not null,number text not null,source_id uuid not null references public.sources(id),external_id text not null,collected_at timestamptz not null,verified boolean not null default false,unique(source_id,external_id));
create table public.contracts(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies(id),company_id uuid not null references public.companies(id),tender_id uuid references public.tenders(id),object text not null,number text not null,amount numeric(18,2) not null check(amount>=0),signed_at date,source_id uuid not null references public.sources(id),external_id text not null,collected_at timestamptz not null,verified boolean not null default false,unique(source_id,external_id));
create table public.works(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.contracts(id),title text not null,neighborhood text not null,subject text not null,status text not null check(status in('planned','ongoing','paused','completed')),latitude numeric check(latitude between -90 and 90),longitude numeric check(longitude between -180 and 180),source_id uuid not null references public.sources(id),external_id text not null,collected_at timestamptz not null,verified boolean not null default false,unique(source_id,external_id));
create table public.measurements(id uuid primary key default gen_random_uuid(),work_id uuid not null references public.works(id),measured_at date not null,progress numeric(5,2) not null check(progress between 0 and 100),amount numeric(18,2) check(amount>=0),source_id uuid not null references public.sources(id),external_id text not null,collected_at timestamptz not null,verified boolean not null default false,unique(source_id,external_id));
create table public.commitments(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.contracts(id),number text not null,amount numeric(18,2) not null check(amount>=0),issued_at date not null,source_id uuid not null references public.sources(id),external_id text not null,collected_at timestamptz not null,verified boolean not null default false,unique(source_id,external_id));
create table public.payments(id uuid primary key default gen_random_uuid(),commitment_id uuid not null references public.commitments(id),amount numeric(18,2) not null check(amount>=0),paid_at date not null,source_id uuid not null references public.sources(id),external_id text not null,collected_at timestamptz not null,verified boolean not null default false,unique(source_id,external_id));
create table public.documents(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.sources(id),external_id text not null,contract_id uuid references public.contracts(id),work_id uuid references public.works(id),original_url text not null check(original_url like 'https://%'),sha256 char(64) not null check(sha256 ~ '^[a-f0-9]{64}$'),collected_at timestamptz not null,verified boolean not null default false,unique(source_id,external_id));
create table public.occurrences(id uuid primary key default gen_random_uuid(),citizen_id uuid not null references public.citizens(id),municipality_id uuid references public.municipalities(id),work_id uuid references public.works(id),title text not null check(length(title) between 8 and 120),description text not null check(length(description) between 20 and 3000),neighborhood text not null check(length(neighborhood) between 2 and 80),subject text not null check(subject in('Infraestrutura','Saúde','Educação','Urbanismo','Outro')),photo_path text, status text not null default 'pending' check(status in('pending','published','rejected')),moderated_by uuid references public.citizens(id),moderation_reason text,created_at timestamptz not null default now());
create table public.lai_requests(id uuid primary key default gen_random_uuid(),citizen_id uuid not null references public.citizens(id),title text not null check(length(title) between 8 and 120),body text not null check(length(body) between 20 and 5000),agency text not null check(length(agency) between 2 and 160),status text not null default 'draft' check(status in('draft','submitted','answered','closed')),external_protocol text check(length(external_protocol)<=120),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.import_jobs(id uuid primary key default gen_random_uuid(),submitted_by uuid not null references public.citizens(id),source_url text not null check(source_url like 'https://%'),collected_at date not null,sha256 char(64) not null unique check(sha256 ~ '^[a-f0-9]{64}$'),path text not null,format text not null check(format in('csv','pdf')),status text not null default 'quarantine' check(status in('quarantine','validated','rejected')),created_at timestamptz not null default now());
create table public.audits(id bigint generated always as identity primary key,actor_id uuid,entity text not null,record_id uuid not null,action text not null,occurred_at timestamptz not null default now());
create function public.audit_change() returns trigger language plpgsql security definer set search_path = '' as $$
begin insert into public.audits(actor_id,entity,record_id,action) values(auth.uid(),tg_table_name,coalesce(new.id,old.id),tg_op);return coalesce(new,old);end $$;
create function public.moderate_occurrence(record_id uuid,decision text,reason text) returns void language plpgsql security definer set search_path = '' as $$
begin
 if public.app_role() not in('reviewer','admin') then raise exception 'Forbidden'; end if;
 if decision not in('published','rejected') or reason is null or length(trim(reason)) not between 10 and 500 then raise exception 'Invalid decision'; end if;
 update public.occurrences set status=decision,moderated_by=auth.uid(),moderation_reason=reason where id=record_id and status='pending';
 if not found then raise exception 'No pending occurrence'; end if;
end $$;
create function public.update_lai(request_id uuid,new_status text,protocol text) returns void language plpgsql security definer set search_path = '' as $$
begin
 if auth.uid() is null or new_status not in('draft','submitted','answered','closed') or length(protocol)>120 or (new_status='submitted' and coalesce(trim(protocol),'')='') then raise exception 'Invalid request';end if;
 update public.lai_requests set status=new_status,external_protocol=nullif(protocol,''),updated_at=now() where id=request_id and citizen_id=auth.uid();
 if not found then raise exception 'Forbidden'; end if;
end $$;
-- Explicit grants; policies alone do not confer access.
grant usage on schema public to anon,authenticated;
revoke all on all tables in schema public from anon,authenticated;
grant select on public.municipalities,public.sources to anon,authenticated;
grant select on public.citizens,public.occurrences,public.lai_requests,public.import_jobs,public.audits to authenticated;
grant insert on public.occurrences,public.lai_requests,public.import_jobs to authenticated;
alter table public.municipalities enable row level security;
create trigger audit_municipalities after insert or update or delete on public.municipalities for each row execute function public.audit_change();
alter table public.sources enable row level security;
create trigger audit_sources after insert or update or delete on public.sources for each row execute function public.audit_change();
alter table public.citizens enable row level security;
create trigger audit_citizens after insert or update or delete on public.citizens for each row execute function public.audit_change();
alter table public.occurrences enable row level security;
create trigger audit_occurrences after insert or update or delete on public.occurrences for each row execute function public.audit_change();
alter table public.lai_requests enable row level security;
create trigger audit_lai_requests after insert or update or delete on public.lai_requests for each row execute function public.audit_change();
alter table public.import_jobs enable row level security;
create trigger audit_import_jobs after insert or update or delete on public.import_jobs for each row execute function public.audit_change();
alter table public.audits enable row level security;
alter table public.agencies enable row level security;
create trigger audit_agencies after insert or update or delete on public.agencies for each row execute function public.audit_change();
alter table public.companies enable row level security;
create trigger audit_companies after insert or update or delete on public.companies for each row execute function public.audit_change();
alter table public.tenders enable row level security;
create trigger audit_tenders after insert or update or delete on public.tenders for each row execute function public.audit_change();
alter table public.contracts enable row level security;
create trigger audit_contracts after insert or update or delete on public.contracts for each row execute function public.audit_change();
alter table public.works enable row level security;
create trigger audit_works after insert or update or delete on public.works for each row execute function public.audit_change();
alter table public.measurements enable row level security;
create trigger audit_measurements after insert or update or delete on public.measurements for each row execute function public.audit_change();
alter table public.commitments enable row level security;
create trigger audit_commitments after insert or update or delete on public.commitments for each row execute function public.audit_change();
alter table public.payments enable row level security;
create trigger audit_payments after insert or update or delete on public.payments for each row execute function public.audit_change();
alter table public.documents enable row level security;
create trigger audit_documents after insert or update or delete on public.documents for each row execute function public.audit_change();
grant select on public.agencies to anon,authenticated;
grant insert,update on public.agencies to authenticated;
create policy read_agencies on public.agencies for select using(verified or public.app_role() in('analyst','reviewer','admin'));
create policy insert_agencies on public.agencies for insert to authenticated with check(public.app_role() in('analyst','admin') and verified=false);
create policy review_agencies on public.agencies for update to authenticated using(public.app_role() in('reviewer','admin')) with check(public.app_role() in('reviewer','admin'));
grant select on public.companies to anon,authenticated;
grant insert,update on public.companies to authenticated;
create policy read_companies on public.companies for select using(verified or public.app_role() in('analyst','reviewer','admin'));
create policy insert_companies on public.companies for insert to authenticated with check(public.app_role() in('analyst','admin') and verified=false);
create policy review_companies on public.companies for update to authenticated using(public.app_role() in('reviewer','admin')) with check(public.app_role() in('reviewer','admin'));
grant select on public.tenders to anon,authenticated;
grant insert,update on public.tenders to authenticated;
create policy read_tenders on public.tenders for select using(verified or public.app_role() in('analyst','reviewer','admin'));
create policy insert_tenders on public.tenders for insert to authenticated with check(public.app_role() in('analyst','admin') and verified=false);
create policy review_tenders on public.tenders for update to authenticated using(public.app_role() in('reviewer','admin')) with check(public.app_role() in('reviewer','admin'));
grant select on public.contracts to anon,authenticated;
grant insert,update on public.contracts to authenticated;
create policy read_contracts on public.contracts for select using(verified or public.app_role() in('analyst','reviewer','admin'));
create policy insert_contracts on public.contracts for insert to authenticated with check(public.app_role() in('analyst','admin') and verified=false);
create policy review_contracts on public.contracts for update to authenticated using(public.app_role() in('reviewer','admin')) with check(public.app_role() in('reviewer','admin'));
grant select on public.works to anon,authenticated;
grant insert,update on public.works to authenticated;
create policy read_works on public.works for select using(verified or public.app_role() in('analyst','reviewer','admin'));
create policy insert_works on public.works for insert to authenticated with check(public.app_role() in('analyst','admin') and verified=false);
create policy review_works on public.works for update to authenticated using(public.app_role() in('reviewer','admin')) with check(public.app_role() in('reviewer','admin'));
grant select on public.measurements to anon,authenticated;
grant insert,update on public.measurements to authenticated;
create policy read_measurements on public.measurements for select using(verified or public.app_role() in('analyst','reviewer','admin'));
create policy insert_measurements on public.measurements for insert to authenticated with check(public.app_role() in('analyst','admin') and verified=false);
create policy review_measurements on public.measurements for update to authenticated using(public.app_role() in('reviewer','admin')) with check(public.app_role() in('reviewer','admin'));
grant select on public.commitments to anon,authenticated;
grant insert,update on public.commitments to authenticated;
create policy read_commitments on public.commitments for select using(verified or public.app_role() in('analyst','reviewer','admin'));
create policy insert_commitments on public.commitments for insert to authenticated with check(public.app_role() in('analyst','admin') and verified=false);
create policy review_commitments on public.commitments for update to authenticated using(public.app_role() in('reviewer','admin')) with check(public.app_role() in('reviewer','admin'));
grant select on public.payments to anon,authenticated;
grant insert,update on public.payments to authenticated;
create policy read_payments on public.payments for select using(verified or public.app_role() in('analyst','reviewer','admin'));
create policy insert_payments on public.payments for insert to authenticated with check(public.app_role() in('analyst','admin') and verified=false);
create policy review_payments on public.payments for update to authenticated using(public.app_role() in('reviewer','admin')) with check(public.app_role() in('reviewer','admin'));
grant select on public.documents to anon,authenticated;
grant insert,update on public.documents to authenticated;
create policy read_documents on public.documents for select using(verified or public.app_role() in('analyst','reviewer','admin'));
create policy insert_documents on public.documents for insert to authenticated with check(public.app_role() in('analyst','admin') and verified=false);
create policy review_documents on public.documents for update to authenticated using(public.app_role() in('reviewer','admin')) with check(public.app_role() in('reviewer','admin'));
create policy public_municipalities on public.municipalities for select using(true);
create policy public_sources on public.sources for select using(true);
grant insert,update on public.municipalities,public.sources to authenticated;
create policy manage_municipalities on public.municipalities for all to authenticated using(public.app_role()='admin') with check(public.app_role()='admin');
create policy manage_sources on public.sources for all to authenticated using(public.app_role() in('analyst','admin')) with check(public.app_role() in('analyst','admin'));
create policy own_profile on public.citizens for select to authenticated using(id=auth.uid());
create policy read_occurrences on public.occurrences for select to authenticated using(citizen_id=auth.uid() or public.app_role() in('reviewer','admin'));
create policy create_occurrence on public.occurrences for insert to authenticated with check(citizen_id=auth.uid() and status='pending' and moderated_by is null and moderation_reason is null and (photo_path is null or photo_path like auth.uid()::text||'/%'));
create policy own_lai on public.lai_requests for select to authenticated using(citizen_id=auth.uid());
create policy create_lai on public.lai_requests for insert to authenticated with check(citizen_id=auth.uid() and status='draft' and external_protocol is null);
create policy read_imports on public.import_jobs for select to authenticated using(public.app_role() in('analyst','reviewer','admin'));
create policy create_imports on public.import_jobs for insert to authenticated with check(submitted_by=auth.uid() and public.app_role() in('analyst','reviewer','admin') and status='quarantine' and path like auth.uid()::text||'/%');
create policy read_audits on public.audits for select to authenticated using(public.app_role()='admin');
-- Deliberately curated public projection: never exposes citizen IDs, photos or review notes.
create view public.published_occurrences with (security_barrier=true) as select id,title,description,neighborhood,subject,created_at from public.occurrences where status='published';
grant select on public.published_occurrences to anon,authenticated;
revoke execute on all functions in schema public from public;
grant execute on function public.app_role() to anon,authenticated;
grant execute on function public.moderate_occurrence(uuid,text,text),public.update_lai(uuid,text,text) to authenticated;
create index occurrences_owner_idx on public.occurrences(citizen_id,created_at desc);
create index occurrences_pending_idx on public.occurrences(status) where status='pending';
create index lai_owner_idx on public.lai_requests(citizen_id,created_at desc);
create index contracts_agency_idx on public.contracts(agency_id);
create index works_contract_idx on public.works(contract_id);
commit;
